(6537334, 972600, 108580, '<td valign="top">Africa. Can''t beat it! The dead tree silhouette, the flat tops, the early morning mist, those gradations...beautiful. You have to witness the sunsets/rises here. Photo''s just don''t do it justice. It''s the expectation of what''s hiding in the bush too. I got hammered in my last African sunset where the foreground was also dark and not HRD''d. I prefer it the way I saw it.<br/><br/><i>Message edited by author 2011-09-19 02:09:05.</i></td>', 'Africa. Can''t beat it! The dead tree silhouette, the flat tops, the early morning mist, those gradations...beautiful. You have to witness the sunsets/rises here. Photo''s just don''t do it justice. It''s the expectation of what''s hiding in the bush too. I got hammered in my last African sunset where the foreground was also dark and not HRD''d. I prefer it the way I saw it.', '2011-09-12 10:07:07.000000', '2011-09-19 03:09:05.000000', 1),
(6537351, 972817, 108580, '<td valign="top">Super timing and location. Great exposure and lighting.</td>', 'Super timing and location. Great exposure and lighting.', '2011-09-12 10:24:39.000000', NULL, 1),
