(6537655, 972688, 33352, '<td valign="top">like the Dof in this, and the warmth of the sun</td>', 'like the Dof in this, and the warmth of the sun', '2011-09-12 15:59:21.000000', NULL, 1),
(6537656, 972600, 33352, '<td valign="top">Very moody scene</td>', 'Very moody scene', '2011-09-12 15:59:40.000000', NULL, 1),
(6537657, 972464, 108069, '<td valign="top">Very nice idea. There seems to be a bit of a haze cast to this, though, and I think you would have been well served by some PS tricks to get those roses to pop just a bit. Maybe a levels and/or curves adjustment. A fill flash would have helped in this regard as well. Composition is nice, though. (Not voting, just commenting.)</td>', 'Very nice idea. There seems to be a bit of a haze cast to this, though, and I think you would have been well served by some PS tricks to get those roses to pop just a bit. Maybe a levels and/or curves adjustment. A fill flash would have helped in this regard as well. Composition is nice, though. (Not voting, just commenting.)', '2011-09-12 15:59:51.000000', NULL, 1),
(6537661, 972724, 33352, '<td valign="top">The image take is stronger than the challenge, your use of lighting very good.</td>', 'The image take is stronger than the challenge, your use of lighting very good.', '2011-09-12 16:02:50.000000', NULL, 1),
(6537665, 972783, 108580, '<td valign="top">Fabulous location and great POV, concept.</td>', 'Fabulous location and great POV, concept.', '2011-09-12 16:07:29.000000', NULL, 1),
