(6537805, 972785, 108580, '<td valign="top">Crushed orange or it''s the <strike>bush/brush</strike> veld :) fire smoke tainting everything in the sky right now around Texas. Then again maybe it''s just a bunch of clouds with the sun behind it...art, it''s fickle.</td>', 'Crushed orange or it''s the bush/brush veld :) fire smoke tainting everything in the sky right now around Texas. Then again maybe it''s just a bunch of clouds with the sun behind it...art, it''s fickle.', '2011-09-12 19:37:22.000000', NULL, 1),
(6537811, 972606, 74559, '<td valign="top">My first smile in voting :-) Love the POV! Love the title.</td>', 'My first smile in voting :-) Love the POV! Love the title.', '2011-09-12 19:46:56.000000', NULL, 1),
(6537813, 972009, 74559, '<td valign="top">Wow, excellent work at capturing the sun without blowing out the colors in the sky, great view!</td>', 'Wow, excellent work at capturing the sun without blowing out the colors in the sky, great view!', '2011-09-12 19:49:22.000000', NULL, 1),
