(6537900, 972768, 124982, '<td valign="top">Hmmm....first impression was too much processing. But it''s grown on me. Absolutely love the tones on the shed and the grass. Quite arresting!</td>', 'Hmmm....first impression was too much processing. But it''s grown on me. Absolutely love the tones on the shed and the grass. Quite arresting!', '2011-09-12 22:08:04.000000', NULL, 1),
(6537904, 972690, 124982, '<td valign="top">I know I''ve seen this building in a recent challenge before? Very interesting composition, quite appealing..but no real focal point -- eye wander all over the image without finding a home to settle on. Gave a 7 anyway!</td>', 'I know I''ve seen this building in a recent challenge before? Very interesting composition, quite appealing..but no real focal point -- eye wander all over the image without finding a home to settle on. Gave a 7 anyway!', '2011-09-12 22:09:29.000000', NULL, 1),
(6537907, 972551, 124982, '<td valign="top">Superb. Such a drastic departure from all the other images in this challenge. Different, but wonderfully executed. The detail in the leaf is incredible. Going to go out on a limb here and say this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30861" rel="nofollow" target="_blank">Bear_Music</a>?</td>', 'Superb. Such a drastic departure from all the other images in this challenge. Different, but wonderfully executed. The detail in the leaf is incredible. Going to go out on a limb here and say this is  Bear_Music?', '2011-09-12 22:12:11.000000', NULL, 1),
(6537908, 972302, 124982, '<td valign="top">Would be a lovely image....if only the person was not there.</td>', 'Would be a lovely image....if only the person was not there.', '2011-09-12 22:14:08.000000', NULL, 1),
