(6537998, 972720, 30982, '<td valign="top">Indeed!  A lovely frame, and a lovely frame guard to go with it!</td>', 'Indeed!  A lovely frame, and a lovely frame guard to go with it!', '2011-09-12 23:23:30.000000', NULL, 1),
(6538000, 972772, 30982, '<td valign="top">I like how the clouds so nicely form a body one can attribute the hand as belonging to.</td>', 'I like how the clouds so nicely form a body one can attribute the hand as belonging to.', '2011-09-12 23:24:07.000000', NULL, 1),
(6538002, 972602, 30982, '<td valign="top">Very nice composition!</td>', 'Very nice composition!', '2011-09-12 23:24:34.000000', NULL, 1),
(6538003, 972718, 30982, '<td valign="top">Clever interpretation.</td>', 'Clever interpretation.', '2011-09-12 23:25:00.000000', NULL, 1),
