(6538017, 972858, 30982, '<td valign="top">The crispness you have on the water and the sky is just amazing.  Love that wee little lighthouse amidst the vastness of the sea and the sky.  Nice touch with the processing!</td>', 'The crispness you have on the water and the sky is just amazing.  Love that wee little lighthouse amidst the vastness of the sea and the sky.  Nice touch with the processing!', '2011-09-12 23:31:09.000000', NULL, 1),
(6538018, 972809, 30982, '<td valign="top">Great title and very nice interpretation of the challenge!</td>', 'Great title and very nice interpretation of the challenge!', '2011-09-12 23:31:28.000000', NULL, 1),
(6538019, 972418, 30982, '<td valign="top">This just soars - both the bird over the valley and the photograph itself.  Wonderful streaks of light reaching out; excellent tones throughout.</td>', 'This just soars - both the bird over the valley and the photograph itself.  Wonderful streaks of light reaching out; excellent tones throughout.', '2011-09-12 23:32:17.000000', NULL, 1),
(6538021, 972470, 30982, '<td valign="top">When I first saw this on the thumbnail page I was a bit taken aback by the long narrow framing, but oh does it work!  In fact, this would make a great bookmark, in addition to a killer print.</td>', 'When I first saw this on the thumbnail page I was a bit taken aback by the long narrow framing, but oh does it work!  In fact, this would make a great bookmark, in addition to a killer print.', '2011-09-12 23:33:18.000000', NULL, 1),
(6538022, 972866, 30982, '<td valign="top">I like the industrial semi-apocalyptic feel of this.</td>', 'I like the industrial semi-apocalyptic feel of this.', '2011-09-12 23:33:38.000000', NULL, 1),
(6538037, 972773, 57447, '<td valign="top">Glad to see light on the flowers not just a silhouette.</td>', 'Glad to see light on the flowers not just a silhouette.', '2011-09-12 23:44:59.000000', NULL, 1),
(6538038, 972689, 57447, '<td valign="top">and follows the path of the train.  Nice.</td>', 'and follows the path of the train.  Nice.', '2011-09-12 23:46:10.000000', NULL, 1),
