(6538360, 972885, 108069, '<td valign="top">Or lack thereof. Cross processing gives it a gloomy mood, and being stuck in traffic in the haze, it''s quite fitting. Just the hint of cars in contrast to the bright sun makes the mind wander elsewhere to better things than stop-and-go. Cool shot.</td>', 'Or lack thereof. Cross processing gives it a gloomy mood, and being stuck in traffic in the haze, it''s quite fitting. Just the hint of cars in contrast to the bright sun makes the mind wander elsewhere to better things than stop-and-go. Cool shot.', '2011-09-13 11:13:29.000000', NULL, 1),
(6538363, 972786, 108069, '<td valign="top">Nice shot. The vignette is a bit much, but I do like how it mimics the starburst sun. Pattern replication. Nice tones.</td>', 'Nice shot. The vignette is a bit much, but I do like how it mimics the starburst sun. Pattern replication. Nice tones.', '2011-09-13 11:14:27.000000', NULL, 1),
(6538365, 972470, 108069, '<td valign="top">Reminiscent of a triptych panel. Cool shapes and contrast, great color and silhouette. Interesting stuff.</td>', 'Reminiscent of a triptych panel. Cool shapes and contrast, great color and silhouette. Interesting stuff.', '2011-09-13 11:16:21.000000', NULL, 1),
(6538366, 972764, 108069, '<td valign="top">Beauty. Framed indeed. Nice tones and silhouette. Pretty shot.</td>', 'Beauty. Framed indeed. Nice tones and silhouette. Pretty shot.', '2011-09-13 11:17:08.000000', NULL, 1),
(6538367, 972554, 108069, '<td valign="top">Cool photo. Vignette is pretty serious, but it adds to the photo here. Nice tones.</td>', 'Cool photo. Vignette is pretty serious, but it adds to the photo here. Nice tones.', '2011-09-13 11:18:20.000000', NULL, 1),
(6538368, 972455, 108069, '<td valign="top">Great shot. Powerful and moody.</td>', 'Great shot. Powerful and moody.', '2011-09-13 11:19:15.000000', NULL, 1),
